// --------------------------------------------------------------- sum_yields

/// `_sum_yields`: total eval-points a set of yield triples is worth at
/// weight vector `w`, crediting the short `culture`/`science` RATE spelling
/// at `credit` (`w.get(card_rate_credit)`, resolved ONCE by the caller and
/// threaded through here -- `card_potential` may call this several times per
/// card while pricing board terms, and re-reading the same weight each time
/// would be pure waste).
///
/// Python memoizes the other four credited kinds' weight lookups in a local
/// `dict` within one call, because `w.get(key, default)` there is a
/// `dict.get`. [`Weights::get`](super::weights::Weights::get) is a
/// bounds-checked array index, already as cheap as a memoized read would be,
/// so there is nothing here for a per-call cache to buy back -- reading
/// `w.get(WeightKey::UnitStrengthCredit)` twice in one card's triples (rare:
/// at most one `YieldKind::Unit` triple exists per card today) costs the
/// same as reading it once.
pub fn sum_yields(triples: &[CardYield], w: &Weights, credit: f64) -> f64 {
    let mut total = 0.0;
    for &(key, amount, kind) in triples {
        let mut wk = w.get(key);
        let mut amt = amount;
        match kind {
            YieldKind::Gain => {}
            YieldKind::Cost => {
                if wk < 0.0 {
                    wk = 0.0;
                }
            }
            YieldKind::Rate => amt *= credit,
            YieldKind::Unit => amt *= w.get(WeightKey::UnitStrengthCredit),
            // `1.0 +` the credit, not the credit alone: the same additive
            // shape `card_potential_core`'s `type_bonus` uses for its own
            // six credit-gated dedicated pricers (see that function's top
            // comment). `wk` above already resolved the SAME weight every
            // other card type's matching field prices through (`strength`/
            // `happy_margin`/`civil_actions`/etc.), so the un-credited face
            // value (the `1.0` term) is a genuine, already-fitted price, not
            // a guess; `territory_credit` on top of it is the extra the
            // league is free to climb toward or away from. Before this, a
            // `territory_credit` clamped to exactly 0.0 by `dominance_repair`
            // (trained negative -- a territory's numbers are never a
            // printed COST, so `weights::BENEFIT_GATES` bans a negative
            // credit) multiplied the ONLY price to nothing, blacking out
            // every territory card wherever it landed there -- turning the
            // credit off was worse than never crediting it at all.
            YieldKind::Territory => amt *= 1.0 + w.get(WeightKey::TerritoryCredit),
            YieldKind::Bonus => amt *= w.get(WeightKey::BonusCardCredit),
        }
        if wk != 0.0 && amt != 0.0 {
            total += wk * amt;
        }
    }
    total
}

// -------------------------------------------------- how much board to believe

/// `_BOARD_CREDIT_KEYS`/`_board_credit_key`: the per-type offset on top of
/// `card_board_credit` for a card whose pricing is board-aware and has NO
/// dedicated board-aware pricing function of its own (leader). `None` for
/// every other type -- either there is nothing to offset, or (Government/
/// Action/Wonder, see below) a dedicated function already owns the pricing
/// and a second, generic offset would be dead weight. Bonus used to have one
/// too (`CardBoardBonus`); RETIRED 2026-08-24 (`weights::RETIRED_KEYS`) --
/// not shadowed by a dedicated function the way Government/Action/Wonder
/// are, but structurally dead: `credit_board`'s two consumers below
/// (`board_yields::board_yields`'s swap diff, gated on `is_swap_type`, and
/// `board_yields::board_extra`, which never emits a triple for a
/// `CardType::Bonus` card) are unreachable/zero for a Bonus card for every
/// possible weight vector. See that retirement's own `RETIRED_KEYS` entry.
///
/// Deliberately exhaustive over every [`CardType`] variant, NOT a `match`
/// with a trailing `_ => None` -- docs/OPEN_ITEMS.md's own account of why
/// `Bonus` needed a branch here is exactly the bug shape a wildcard arm
/// invites: a card category present in [`CardType`] but silently absent
/// from this registry, with nothing failing when they disagree until
/// someone asks why a whole class prices as if it isn't there
/// (`row_pressure` was blind to `class:bonus` for precisely this reason).
/// Adding a category later is a compile error here until a human decides
/// its credit key on purpose, matching `WeightKey::group`'s own reasoning
/// in `weights.rs` for banning the same wildcard shape. See also
/// `tests::board_credit_key_is_exhaustive_and_only_none_for_types_with_no_board_credit_concept`.
pub fn board_credit_key(id: CardId) -> Option<WeightKey> {
    use CardType::*;
    match id.get().kind {
        Leader => Some(WeightKey::CardBoardLeader),

        // No board-aware pricing concept exists in THIS table for these --
        // not "unpriced", just priced a different way. A build (Farm/Mine/
        // urban/unit/SpecialTech) is priced by `tech_value` gated on
        // `tech_board_credit` directly, never through this per-type OFFSET
        // table at all (see `card_potential`'s dispatch, which returns
        // before ever calling this function for a levelled type). Tactic/
        // Aggression/War/Pact/Event (docs/OPEN_ITEMS.md item 2, closed
        // 2026-08-06) now follow the exact same shape: `tactic_value`/
        // `aggression_value`/`war_hand_value`/`pact_value`/`event_prepare_
        // value`, each gated on its own `*_board_credit`, dispatched from
        // `card_potential` before this function is ever reached for one of
        // the five. Territory is priced a third way, through the static
        // table (`card_yields`'s `YieldKind::Territory` branch,
        // `territory_credit`) -- see this module's top doc comment for why
        // Territory was never truly part of item 2's "prices at 0.0" claim
        // despite being named alongside these five in earlier drafts of
        // this comment.
        //
        // Government/Action/Wonder joined this `None` bucket 2026-08-13
        // (SIGNAUDIT.txt), moving OUT of a `Some(WeightKey::CardBoard*)`
        // arm each used to have: `card_potential_core`'s dedicated
        // `gov_value`/`action_value` branches and Wonder's own
        // `board_yields::board_yields` swap-diff branch, gated on
        // `gov_board_credit`/`action_board_credit`/`wonder_board_credit`
        // respectively, ALREADY dispatch and unconditionally `return`
        // before this function is ever reached for one of the three,
        // exactly like the levelled-type and military-deck cases above --
        // this file's own doc comment simply had not noticed the shape
        // applied to these three as well when it was first written.
        // `gov_board_credit`/`action_board_credit` default nonzero (1.0,
        // "measured effective from the start"), so the two per-type keys
        // that used to sit here (`card_board_government`/
        // `card_board_action`) were dead on EVERY trained champion by
        // construction; `wonder_board_credit` defaults 0.0 but is climbed
        // away from it in practice, making `card_board_wonder` dead the
        // same way once trained. All three retired (`WeightKey::
        // RETIRED_KEYS`) rather than left as live-looking knobs wired to
        // nothing.
        //
        // `Bonus` joined this bucket 2026-08-24, moving OUT of its own
        // `Some(WeightKey::CardBoardBonus)` arm -- a DIFFERENT shape than
        // Government/Action/Wonder above (no dedicated function shadows it;
        // it never had one). `credit_board`'s two consumers in
        // `card_potential_core` are `board_yields::board_yields`'s swap diff
        // (requires `is_swap_type`: Leader/Government/Wonder, never Bonus)
        // and `board_yields::board_extra` (only ever emits a triple for a
        // card carrying `Special::CulturePerCivilizationWithMoreCulture` or
        // `Special::ResourcesForMilitaryUnitsPerStrongerCivilization` --
        // checked against `card_table.rs`: the three cards with either
        // special are all `CardType::Action`, never Bonus). So both
        // consumers are unreachable/zero for a Bonus card regardless of this
        // weight's value -- structurally dead, not merely unreached on the
        // sampled champions. See `weights::RETIRED_KEYS`'s own entry.
        Farm | Mine | Lab | Temple | Library | Arena | Theater | Infantry | Cavalry | Artillery
        | Air | SpecialTech | Tactic | Aggression | War | Pact | Territory | Event | Government
        | Action | Wonder | Bonus => None,
    }
}

/// `_swap_type`: `Some(kind)` for a single-slot card (leader/government),
/// else `None`. Deliberately [`board_yields::is_single_slot`], NOT
/// [`board_yields::is_swap_type`]: a wonder is priced by a swap diff too, but
/// two wonders in hand can both be built, so collapsing them the way two
/// leaders (only one of which you can ever hold) collapse would be wrong.
/// See the two predicates' own doc comments in `board_yields.rs`.
pub fn swap_type(id: CardId) -> Option<CardType> {
    let kind = id.get().kind;
    board_yields::is_single_slot(kind).then_some(kind)
}

// ---------------------------------------------- the two ring-fenced yields

/// `_RESTRICTED_TO_FEATURE`: `resource_discount` is not a live `evaluate`
/// coordinate (`features()` never emits it), so no game the league plays can
/// put a gradient on it directly. It IS a resource though, so
/// [`yield_marginal`] reroutes it through `resource_stock`'s marginal
/// instead, scaled by a credit weight: what fraction of a whole resource
/// this ring-fenced one is actually worth. `resource_discount` is credited
/// at its OWN coordinate -- a discount is worth a whole resource only when
/// the build was going to happen anyway, which is a judgement the climb is
/// entitled to make, so 1.0 is its authored default and not a law.
///
/// Crediting `resource_discount` at a hardcoded 1.0 made its own coordinate
/// unreadable, and a coordinate nothing reads is a coordinate the climb
/// random-walks for free: the three live champions had drifted it to 0.05,
/// 4.04 and 0.32 with no gradient anywhere in the league to have put it
/// there.
///
/// `restricted_resources` used to reroute here too, keyed off a second
/// `WeightKey` variant that existed ONLY so this function had something to
/// match on -- a coordinate nothing but this dispatch ever read, and
/// therefore a coordinate the climb was free to random-walk exactly like
/// `resource_discount` used to be before the fix above. That variant is
/// retired outright (`weights::RETIRED_KEYS`); [`Priced::RestrictedResources`]
/// is the tag that survives it, and [`priced_marginal`]/[`priced_weight`]
/// carry the same `resource_stock` * `restricted_resource_credit` formula
/// this function used to run for it, clamp and all -- see those functions'
/// own doc comments.
fn restricted_to_feature(key: WeightKey) -> Option<(WeightKey, WeightKey)> {
    if key == WeightKey::ResourceDiscount {
        Some((WeightKey::ResourceStock, WeightKey::ResourceDiscount))
    } else {
        None
    }
}

/// `_yield_marginal`: [`rivals::feature_marginal`], plus the ring-fenced
/// `resource_discount` pseudo-feature above. `idx: u8`/`late: Option<f64>`
/// match `rivals::feature_marginal`'s own signature exactly (see this
/// module's top doc comment on the `idx` width mismatch with
/// `board_yields.rs`); `ctx` is always `None` here, matching Python's
/// `_yield_marginal(key, state, idx, w, late)` -- it never threads a
/// `RivalContext` through, unlike `strength_marginal`'s other callers.
///
/// The ring-fenced branch clamps its `feature_marginal` read to
/// `max(0.0, ...)` for the same reason [`YieldKind::Cost`] does: a GAIN
/// (a discount) must never read as a loss because a hill climb drove
/// `resource_stock` negative. [`priced_marginal`]'s `RestrictedResources`
/// arm repeats the same clamp for the other ring-fenced route, now that it
/// has no `WeightKey` to reach this function through.
pub fn yield_marginal(key: WeightKey, state: &GameState, idx: u8, w: &Weights, late: Option<f64>) -> f64 {
    match restricted_to_feature(key) {
        None => rivals::feature_marginal(key, state, idx, w, late, None),
        Some((feat, credit)) => {
            let c = w.get(credit);
            if c == 0.0 {
                0.0
            } else {
                c * rivals::feature_marginal(feat, state, idx, w, late, None).max(0.0)
            }
        }
    }
}

/// [`feature_key`]'s return type. Every [`board_yields::Feature`] names a
/// live [`WeightKey`] EXCEPT `RestrictedResources`, which used to be one
/// (see `restricted_to_feature`'s doc comment for why that was a hazard):
/// a coordinate read ONLY as a dispatch tag by `restricted_to_feature`,
/// never as a number, could still be indexed and mutated by a hill climb
/// like any other weight. `Priced::RestrictedResources` is the same
/// dispatch tag with no `WeightKey` behind it, so there is no longer a slot
/// for a climb to random-walk.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Priced {
    Key(WeightKey),
    RestrictedResources,
}

/// State-aware reader for a [`Priced`] key -- [`feature_key`]'s marginal,
/// wherever a `GameState` is in scope. `Priced::Key(k)` is exactly
/// [`yield_marginal`] (so `ResourceDiscount`'s own ring-fenced route still
/// runs whenever `feature_key` happens to reach it, though in practice it
/// never does -- `board_yields::Feature` has no `ResourceDiscount`
/// variant). `Priced::RestrictedResources` runs the SAME clamp-and-multiply
/// formula [`restricted_to_feature`] used to run for it when it was still a
/// `WeightKey`: `restricted_resource_credit` gates it (a zero credit reads
/// as a flat 0.0, never a divide-by-zero or a sign flip), and the
/// `resource_stock` marginal it scales is clamped to `max(0.0, ...)` so a
/// hill climb that has driven `resource_stock` negative can never make a
/// ring-fenced resource read as a loss.
fn priced_marginal(key: Priced, state: &GameState, idx: u8, w: &Weights, late: Option<f64>) -> f64 {
    match key {
        Priced::Key(k) => yield_marginal(k, state, idx, w, late),
        Priced::RestrictedResources => {
            let c = w.get(WeightKey::RestrictedResourceCredit);
            if c == 0.0 {
                0.0
            } else {
                c * rivals::feature_marginal(WeightKey::ResourceStock, state, idx, w, late, None).max(0.0)
            }
        }
    }
}

/// Stateless reader for a [`Priced`] key -- [`sum_board_triples`]/
/// [`gains_only_board_sum`] have no `GameState` in scope (they price a
/// SWAP diff's flat triples, already board-derived, at a plain `w.get`) so
/// they cannot run [`priced_marginal`]'s marginal formula. `Priced::Key(k)`
/// is the ordinary `w.get(k)` those two functions always did.
/// `Priced::RestrictedResources` reads `0.0`: it cannot honestly compute the
/// ring-fenced marginal with no state to read `resource_stock` from, and it
/// does not need to -- `board_yields::board_extra` is the ONLY producer of a
/// `Feature::RestrictedResources` triple, its output reaches exactly two
/// call sites (`cards::action_value`, which prices it correctly through
/// [`priced_marginal`], and `card_potential_core`'s generic fallback, which
/// reaches this function instead), and that fallback is gated on
/// `action_board_credit == 0.0`, the SAME "dead on every trained champion by
/// construction" default `weights::RETIRED_KEYS`'s `card_board_action` entry
/// already documents (`action_board_credit` defaults to a nonzero 1.0, and
/// no trained hill climb has ever landed on exactly 0.0). Reading `0.0` here
/// is therefore provably identical, on every real weight vector, to the
/// flat `w.get(WeightKey::RestrictedResources)` this arm replaces -- that
/// coordinate's own default was `0.0` and nothing in this codebase's
/// history ever measured a trained champion where this branch executed at
/// all.
fn priced_weight(key: Priced, w: &Weights) -> f64 {
    match key {
        Priced::Key(k) => w.get(k),
        Priced::RestrictedResources => 0.0,
    }
}

