    #[test]
    fn is_action_and_is_government_match_the_type_they_name() {
        assert!(CardId::by_name("Reserves (I)").unwrap().kind().is_action());
        assert!(!CardId::by_name("Despotism").unwrap().kind().is_action());
        assert!(CardId::by_name("Despotism").unwrap().kind().is_government());
        assert!(!CardId::by_name("Reserves (I)").unwrap().kind().is_government());
    }

